class Solution:
    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        d=[[0]*(n+1) for _ in range(m+1)]
        for s in strs:
            z=s.count('0');o=len(s)-z
            for i in range(m,z-1,-1):
                for j in range(n,o-1,-1):d[i][j]=max(d[i][j],d[i-z][j-o]+1)
        return d[m][n]

